def solve_a_n(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, so k = n/2
        k = n // 2
        result = 2 * solve_a_n(k, memo) + k
    else:
        # n = 2k+1, so k = (n-1)/2
        k = (n - 1) // 2
        # k+1 = (n+1)/2
        result = solve_a_n(k, memo) + solve_a_n(k + 1, memo) + k

    memo[n] = result
    return result

memo = {}
target_n = 2025
result = solve_a_n(target_n, memo)
print(f"a_{target_n} = {result}")
